package com.whaa.shop.catalog.controller;import com.whaa.shop.catalog.application.CategoryService;import com.whaa.shop.catalog.domain.Category;import com.whaa.shop.common.api.ApiResponse;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController public class CategoryController {private final CategoryService service;public CategoryController(CategoryService s){service=s;}@GetMapping("/api/v1/shop/categories")ApiResponse<List<Category>> shop(){return ApiResponse.ok(service.list(true));}@GetMapping("/api/v1/shop/categories/tree")ApiResponse<List<CategoryNode>> tree(){List<Category> all=service.list(true);return ApiResponse.ok(all.stream().filter(c->c.getParentId()==null).map(p->new CategoryNode(p.getId(),p.getName(),p.getSortOrder(),all.stream().filter(c->p.getId().equals(c.getParentId())).map(c->new CategoryNode(c.getId(),c.getName(),c.getSortOrder(),List.of())).toList())).toList());}@GetMapping("/api/v1/admin/categories")ApiResponse<List<CategoryView>> admin(){List<Category> all=service.list(false);return ApiResponse.ok(all.stream().map(c->new CategoryView(c.getId(),c.getParentId(),c.getName(),c.getSortOrder(),c.getEnabled(),c.getParentId()==null?"顶级分类":all.stream().filter(p->p.getId().equals(c.getParentId())).map(Category::getName).findFirst().orElse("未知分类"))).toList());}@PostMapping("/api/v1/admin/categories")ApiResponse<Category> create(@RequestBody Category c){c.setId(null);return ApiResponse.ok(service.save(c));}@PutMapping("/api/v1/admin/categories/{id}")ApiResponse<Category> update(@PathVariable Long id,@RequestBody Category c){c.setId(id);return ApiResponse.ok(service.save(c));}@DeleteMapping("/api/v1/admin/categories/{id}")ApiResponse<Void> delete(@PathVariable Long id){service.delete(id);return ApiResponse.ok();}public record CategoryNode(Long id,String name,Integer sortOrder,List<CategoryNode> children){}public record CategoryView(Long id,Long parentId,String name,Integer sortOrder,Boolean enabled,String parentName){} }
